-- Concurrent review safeguard: seed only missing rows. Never overwrite an existing
-- explanation or approval; live edits require importer snapshot/hash/CAS checks.
-- Explicações por artigo — CTB (Lei 9.503/1997), continuação a partir do
-- art. 193 (retomada da checkpoint doc/library/ctb-checkpoint-2026-10-13.md),
-- seguindo o mesmo padrão da tabela legal_unit_explanations criada e
-- pilotada hoje na Lei 12.850 (commit 80c9030). Texto oficial conferido em
-- planalto.gov.br/ccivil_03/leis/l9503compilado.htm (13/10/2026). Entram
-- como 'under_review'.

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Proíbe transitar com o veículo em locais destinados a pedestres, ciclistas ou à proteção viária: calçada, passeio, passarela, ciclovia/ciclofaixa, ilha, refúgio, canteiro central, acostamento, marcas de canalização, gramados e jardins públicos. É infração gravíssima, com multa triplicada — uma das penalidades mais severas do capítulo de infrações.', '["Rol fechado de locais protegidos: calçada, passeio, passarela, ciclovia, ciclofaixa, ilha, refúgio, ajardinamento, canteiro central, acostamento, marca de canalização, gramado e jardim público.","Infração gravíssima com multa de TRÊS VEZES o valor-base, uma das multiplicações mais altas do CTB."]'::jsonb, '["A multa não é apenas ''gravíssima'' no sentido genérico: é gravíssima COM multiplicador de 3x, distinto de outras infrações gravíssimas que não têm esse agravamento financeiro.","Acostamento está no rol: transitar por ele para ''furar fila'' também se enquadra aqui."]'::jsonb, 'Um motorista, para evitar um congestionamento, invade o acostamento e depois sobe na calçada para contornar o trânsito parado. Ambas as condutas se enquadram no art. 193: infração gravíssima, multa triplicada.', '["Assertiva que classifica a conduta como infração ''grave'' (não gravíssima) erra a gravidade.","Assertiva que afirma multa simples (1x), sem o multiplicador de três vezes, erra o valor da penalidade."]'::jsonb, '[{"termo":"Marcas de canalização","significado":"Sinalização viária horizontal (ilhas, setas, hachuras) que direciona o fluxo e separa movimentos de veículos."}]'::jsonb, '["Art. 194 (marcha à ré indevida)","Art. 206 (retorno proibido passando por calçada/canteiro)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-193'
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Proíbe dar marcha à ré, salvo na distância estritamente necessária para pequenas manobras (como estacionar) e desde que não gere risco à segurança. É infração grave.', '["Regra geral: marcha à ré é proibida.","Exceção dupla e cumulativa: (1) apenas a distância necessária para pequena manobra e (2) sem causar risco à segurança.","Infração grave (não gravíssima), com multa simples."]'::jsonb, '["Não existe ''direito'' a dar ré em qualquer trecho curto: mesmo uma manobra pequena pode configurar infração se criar risco.","A exceção não autoriza percorrer longas distâncias em marcha à ré, mesmo em vias de pouco movimento."]'::jsonb, 'Um motorista erra a entrada de uma garagem e dá poucos metros de ré, sem tráfego por perto, para se reposicionar e entrar corretamente. Isso se enquadra na exceção (pequena manobra, sem risco). Já dar ré por uma quadra inteira numa avenida movimentada para alcançar uma vaga é infração ao art. 194.', '["Assertiva que trata qualquer marcha à ré como automaticamente proibida, sem considerar a exceção de pequena manobra, está incompleta/errada.","Assertiva que libera marcha à ré longa desde que não haja outros veículos no momento ignora o critério de distância necessária."]'::jsonb, '[{"termo":"Pequena manobra","significado":"Deslocamento mínimo em marcha à ré, tipicamente para estacionar ou se reposicionar, não para percorrer trajeto."}]'::jsonb, '["Art. 193 (vias proibidas de trânsito)","Art. 196 (sinalização de manobra)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-194'
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Pune quem desobedece a uma ordem dada pela autoridade de trânsito ou por seus agentes (por exemplo, um guarda de trânsito mandando parar ou seguir em determinada direção). É infração grave.', '["Abrange qualquer ordem lícita da autoridade de trânsito ou de seus agentes, não apenas sinais de parada.","Infração grave, multa simples."]'::jsonb, '["Distinguir desobedecer a ORDEM de agente (art. 195) de avançar sinal semafórico (art. 208) e de desobedecer sinalização de regulamentação (outros artigos): o art. 195 é especificamente sobre ordem humana direta da autoridade/agente."]'::jsonb, 'Um agente de trânsito, em um cruzamento com semáforo quebrado, faz sinal manual para o motorista parar; o motorista ignora e segue. Configura-se infração ao art. 195 (desobediência à ordem do agente), independentemente do estado do semáforo.', '["Assertiva que trata essa conduta como infração ao art. 208 (sinal vermelho) em vez do art. 195 confunde desobediência a agente com avanço de sinal luminoso."]'::jsonb, '[{"termo":"Autoridade de trânsito","significado":"Órgão ou entidade executivo de trânsito com competência para fiscalizar e aplicar o CTB, ou seus agentes credenciados."}]'::jsonb, '["Art. 208 (avançar sinal vermelho)","Art. 162, I (dirigir sem CNH é distinto, mas ambos tratam de infrações ao condutor)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-195'
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Pune quem deixa de sinalizar com antecedência (por gesto de braço regulamentar ou luz indicadora/seta) o início da marcha, a parada, a mudança de direção ou a mudança de faixa. É infração grave.', '["Quatro manobras exigem sinalização prévia: iniciar marcha, parar, mudar de direção, mudar de faixa.","A sinalização pode ser por gesto de braço OU luz indicadora (pisca-alerta direcional).","Infração grave, multa simples."]'::jsonb, '["A exigência é de sinalizar COM ANTECEDÊNCIA — sinalizar no exato instante da manobra (ou depois de iniciá-la) não cumpre o dispositivo.","Mudar de faixa também exige sinalização prévia, não apenas mudar de direção em cruzamento."]'::jsonb, 'Um motorista muda de faixa na avenida sem acionar a seta, surpreendendo quem vinha atrás. Mesmo sem colisão, há infração ao art. 196 por falta de sinalização prévia da mudança de faixa.', '["Assertiva que limita o dever de sinalização apenas a ''mudança de direção em cruzamento'', excluindo mudança de faixa, está incompleta frente ao texto do artigo."]'::jsonb, '[{"termo":"Gesto regulamentar de braço","significado":"Sinal manual padronizado previsto na regulamentação do Contran para indicar manobra, alternativo à luz indicadora."}]'::jsonb, '["Art. 197 (deslocamento antecipado para faixa de manobra)","Art. 198 (passagem pela esquerda)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-196'
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Pune quem deixa de se deslocar com antecedência para a faixa mais à esquerda ou mais à direita (dentro da própria mão de direção) quando pretende manobrar para aquele lado. É infração média.', '["Dever de posicionamento prévio: antes de virar à esquerda, ocupar a faixa mais à esquerda disponível na própria mão; antes de virar à direita, ocupar a faixa mais à direita.","Infração média (intermediária entre leve e grave), com multa simples."]'::jsonb, '["Não se trata de sinalizar a manobra (isso é o art. 196): o art. 197 trata do POSICIONAMENTO físico do veículo na faixa correta com antecedência.","''Dentro da respectiva mão de direção'' significa que o motorista não pode invadir a contramão para se posicionar — o deslocamento é dentro do seu próprio sentido de tráfego."]'::jsonb, 'Um motorista pretende virar à esquerda no próximo cruzamento, mas permanece na faixa da direita até o último segundo e corta as demais faixas de repente. Isso configura infração ao art. 197 por falta de deslocamento antecipado para a faixa correta.', '["Assertiva que trata esse artigo como dever de SINALIZAR a manobra confunde-o com o art. 196, que trata da sinalização, não do posicionamento na faixa."]'::jsonb, '[{"termo":"Mão de direção","significado":"O sentido de tráfego em que o veículo está circulando, distinto da pista de sentido contrário."}]'::jsonb, '["Art. 196 (sinalização prévia de manobra)","Art. 206 (operação de retorno)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-197'
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Pune quem deixa de ceder passagem pela esquerda a outro veículo, quando solicitado (tipicamente por sinal de luz ou buzina de quem deseja ultrapassar). É infração média.', '["Dever de ceder passagem pela esquerda mediante solicitação do veículo que deseja ultrapassar.","Infração média, multa simples."]'::jsonb, '["O dever surge quando HÁ solicitação (sinal do outro condutor) — não é uma obrigação genérica de sempre andar na faixa da direita, embora essa seja outra regra distinta do CTB (manter-se à direita, salvo para ultrapassar)."]'::jsonb, 'Um motorista trafega na faixa da esquerda em velocidade baixa; o veículo de trás pisca os faróis pedindo passagem para ultrapassar, mas o motorista da frente não se desloca para a direita. Há infração ao art. 198.', '["Assertiva que trata esse dever como automático e independente de qualquer solicitação do veículo de trás ignora o requisito ''quando solicitado'' do texto legal."]'::jsonb, '[{"termo":"Solicitar passagem","significado":"Sinalizar (farol alto intermitente, seta) o desejo de ultrapassar, pedindo que o veículo da frente ceda a faixa da esquerda."}]'::jsonb, '["Art. 199 (ultrapassagem pela direita)","Art. 29 (regras gerais de circulação e velocidade)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-198'
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Proíbe ultrapassar pela direita, EXCETO quando o veículo da frente estiver posicionado na faixa apropriada e sinalizando que vai virar à esquerda (nesse caso, ultrapassá-lo pela direita é permitido). É infração média.', '["Regra geral: ultrapassagem é pela esquerda.","Exceção: veículo da frente posicionado para virar à esquerda e sinalizando isso — aí a ultrapassagem pela direita é permitida.","Infração média, multa simples."]'::jsonb, '["A exceção exige DOIS requisitos cumulativos: o veículo da frente estar na faixa apropriada para virar à esquerda E estar sinalizando essa intenção — não basta apenas estar mais lento."]'::jsonb, 'Um carro reduz a velocidade e se posiciona na faixa mais à esquerda, com a seta esquerda ligada, para fazer a conversão. O veículo de trás pode, nesse caso específico, ultrapassá-lo pela direita sem cometer infração.', '["Assertiva que trata qualquer ultrapassagem pela direita como sempre proibida, sem mencionar a exceção do próprio art. 199, está incompleta."]'::jsonb, '[{"termo":"Faixa apropriada","significado":"A faixa de circulação correta para realizar a manobra pretendida, aqui a mais à esquerda, para quem vai virar à esquerda."}]'::jsonb, '["Art. 200 (proibição de ultrapassar coletivo/escolar parado)","Art. 202 (locais onde é proibido ultrapassar por qualquer lado)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-199'
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Proíbe ultrapassar pela direita um veículo de transporte coletivo ou escolar que esteja parado para embarque/desembarque de passageiros, salvo quando houver refúgio de segurança protegendo o pedestre. É infração gravíssima — a mais grave entre as ultrapassagens indevidas, por envolver risco direto a pedestres (muitas vezes crianças, no caso de escolares).', '["Objeto protegido: veículo de transporte coletivo OU escolar, parado para embarque/desembarque.","Proibição: ultrapassar pela direita (lado dos passageiros descendo/subindo).","Exceção: existência de refúgio de segurança que proteja o pedestre.","Infração gravíssima, multa simples (sem multiplicador, diferente do art. 193)."]'::jsonb, '["A gravidade (gravíssima) decorre do risco a pedestres — frequentemente escolares — descendo ou subindo do veículo parado, não da simples proibição de ultrapassagem pela direita em si.","Diferente do art. 199 (ultrapassagem pela direita em geral, infração média), este artigo trata especificamente de veículo coletivo/escolar PARADO para embarque/desembarque, com penalidade muito mais severa."]'::jsonb, 'Um motorista, impaciente com um ônibus escolar parado liberando crianças, ultrapassa-o pela direita, passando perto da calçada onde elas descem. Essa conduta é infração gravíssima ao art. 200, por colocar em risco direto os pedestres, salvo se houver refúgio de segurança protegendo-os.', '["Assertiva que classifica essa conduta como infração ''média'' (confundindo com a regra geral do art. 199) subestima a gravidade correta, que é gravíssima."]'::jsonb, '[{"termo":"Refúgio de segurança","significado":"Espaço físico protegido na via, entre a faixa de rolamento e a área de embarque/desembarque, que resguarda o pedestre do fluxo de veículos."}]'::jsonb, '["Art. 199 (ultrapassagem pela direita em geral)","Art. 201 (distância mínima ao ultrapassar bicicleta)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-200'
on conflict (unit_id) do nothing;

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Pune quem deixa de guardar a distância lateral mínima de um metro e cinquenta centímetros ao passar por, ou ultrapassar, uma bicicleta. É infração média.', '["Distância lateral mínima: 1,5 metro (um metro e cinquenta centímetros).","Aplica-se tanto ao passar quanto ao ultrapassar ciclista.","Infração média, multa simples."]'::jsonb, '["A regra é de distância LATERAL (de lado), não de distância longitudinal (à frente/atrás) como em outras normas de seguimento de veículos — não confundir os dois tipos de distância de segurança.","1,5 metro é o mínimo absoluto, independentemente da velocidade do automóvel no momento (diferente de outras normas de distância que variam conforme velocidade)."]'::jsonb, 'Em uma via estreita, um motorista ultrapassa um ciclista a apenas 80 centímetros de distância lateral, sem reduzir a velocidade nem aguardar espaço seguro. Essa conduta configura infração ao art. 201 por descumprir a distância mínima de 1,5 metro.', '["Assertiva que fixa a distância mínima em ''um metro'' (sem os cinquenta centímetros) erra o valor exato previsto no CTB."]'::jsonb, '[{"termo":"Distância lateral","significado":"Espaço de separação de lado a lado entre o veículo e o ciclista, medido perpendicularmente ao sentido de deslocamento."}]'::jsonb, '["Art. 200 (ultrapassagem de coletivo/escolar parado)","Art. 29 (regras gerais aplicáveis a ciclistas na via)"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'transito' and u.unit_key = 'art-201'
on conflict (unit_id) do nothing;
